insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90e66462-8fdd-4fa4-a574-bda55becad8c', 'ja', '駆け引きを続けていいかどうかは、どうやって判断しますか？', '["やり取りの雰囲気についての、自分の直感を信じる", "自分がどう感じるかではなく、彼女がどう反応するかを見る", "関心をはっきり言葉にしてくれるのを探す", "会話が十分長く続いているかどうかを見きわめる"]'::jsonb, '自分がどう感じるかではなく、彼女の反応と、気持ちの入り方を見ましょう。')
