insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ae2493f-bf71-457d-8f09-996e6cf2b464', 'ja', '駆け引きにおける「尊重」とは、どういうことですか？', '["自分の結果よりも、彼女の心地よさと境界線を大切にすること", "やり取りのあいだ、ずっと自信を持っていること", "強引になりすぎず、彼女を対等に扱うこと"]'::jsonb, '自分の成功よりも彼女の心地よさを大切にするとき、駆け引きは相手を尊重したものであり続けます。')
