insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df3d8e11-15af-468e-ba4a-9cca550456d2', 'ja', '関心がお互いのものではないとき、二人ともを守る一番すっきりした方法は何ですか？', '["早めに、礼儀正しく立ち去る", "その場をやわらげるために、冗談を言う", "確かめるために、軽く押してみる", "彼女がはっきり断るのを待つ"]'::jsonb, '早めに、相手を尊重して立ち去ると、その場は軽やかなまま保たれ、二人とも気まずい思いをせずに済みます。')
