insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b1b5eb-51d6-4bae-82e9-d9b516852a92', 'ja', 'いたずら心が、相手を怒らせずにうまくいくのは、何があるときですか？', '["伝え方の温かさ。笑顔が、遊びだとはっきり伝える", "実際の言葉よりも、トーンのほうが大切だということ", "意地悪でも批判的でもない、軽くて意外な切り口", "上のすべて"]'::jsonb, 'いたずら心がうまくいくのは、温かさ、トーン、軽やかさが、批判ではなく遊びだと伝えるときです。')
