insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dd24452-9d73-4619-a644-95a9de2edd1d', 'ja', '目を合わせ続けるのに最も適しているのは、どんな瞬間ですか？', '["自然な間のあいだ", "彼女が気持ちを込めて話しているとき", "彼女の話をさえぎっているあいだ", "会話が少しゆっくりになったとき"]'::jsonb, 'アイコンタクトが一番効くのは、落ち着いた、二人で分かち合う瞬間です。話をさえぎっているときではありません。')
