insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79c89303-fe65-481b-8506-11cd45eaed32', 'ja', '雰囲気は良いのに、離れたままでいます。どんなリスクがありますか？', '["関心がありすぎるように見える", "彼女を居心地悪くさせる", "言葉とは裏腹に、関心がないと伝わる", "進み方が速すぎる"]'::jsonb, '距離が合っていないと、言葉で伝えた関心が損なわれることがあります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7200ef5-2102-4d79-abd9-e518cc3c8af8', 'ja', '小さく一歩近づくと、彼女がさりげなく一歩下がります。これはどういう意味ですか？', '["今は、もっとスペースが必要", "自信を持って粘ってほしいと思っている", "こちらを試している", "こちらをまったく好きではない"]'::jsonb, '一歩下がるのは、拒絶ではなく、情報です。スペースを空けて、合わせ直しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9930259-a42a-49fb-bdd4-9d319fe4fd04', 'ja', '距離の近さをめぐって、居心地の悪さを生む間違いは、どれですか？', '["打ち解ける前に、近づくこと", "彼女の体の反応を無視すること", "距離を少しずつ調整すること", "彼女が身を寄せているのに、固まったままでいること"]'::jsonb, '居心地の悪さは、相手の反応を無視したり、それに応えなかったりすることから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c56a1006-a63d-4532-801e-49829be4ccd2', 'ja', '体のミラーリングは、何を伝える助けになりますか？', '["まねによる、惹かれる気持ち", "支配とコントロール", "人と一緒にいるうえでの、安全と安心", "姿勢による自信"]'::jsonb, 'ミラーリングは、無意識のレベルで、親しみと心地よさを伝え、打ち解けるのを助けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a5612de-f9a6-4bc1-bcbb-29d29d0b1f91', 'ja', '彼女は、会話のあいだ、静かにゆっくり話します。何を合わせるべきですか？', '["彼女を元気づけるために、声を大きくする", "もとの大きな声のままでいる", "流れを保つために、早口で話す", "声を落とし、ペースをゆっくりにする"]'::jsonb, '彼女のエネルギーとトーンに合わせると、無意識のうちに打ち解けていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dc61f4a-f296-4e9b-ae8f-01bd4a923b88', 'ja', '彼女がこちらをミラーリングしているかもしれないサインは、どれですか？', '["こちらが姿勢を変えたあと、似た姿勢を取る", "こちらの話すペースに合わせる", "質問が増える", "体の向きを、こちらへ向け直す"]'::jsonb, '体とエネルギーがそろうことは、多くの場合、心地よさと関わりを示しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
